module counter_32bit #(
    parameter WIDTH = 32
)(
    input  wire             clk,        // Clock
    input  wire             rst_n,      // Active-low reset
    input  wire             enable,     // Count enable
    input  wire             load,       // Load preset value
    input  wire [WIDTH-1:0] load_value, // Preset value to load
    input  wire [1:0]       mode,       // Counter mode
    output reg  [WIDTH-1:0] count,      // Current count value
    output wire             overflow,   // Overflow flag
    output wire             zero        // Zero flag
);

reg [WIDTH-1:0] next_count;
reg [1:0] direction;

always @(*) begin
    case (mode)
        2'b00: begin // UP
            next_count = count + (enable ? 1 : 0);
            direction = 2'b00;
        end
        2'b01: begin // DOWN
            next_count = count - (enable ? 1 : 0);
            direction = 2'b01;
        end
        2'b10: begin // UP-DOWN
            if (direction == 2'b00) begin
                next_count = count + (enable ? 1 : 0);
                if (next_count == {WIDTH{1'b1}}) begin
                    direction = 2'b01;
                end
            end else begin
                next_count = count - (enable ? 1 : 0);
                if (next_count == {WIDTH{1'b0}}) begin
                    direction = 2'b00;
                end
            end
        end
        default: begin
            next_count = count;
            direction = 2'b00;
        end
    endcase
end

always @(posedge clk) begin
    if (~rst_n) begin
        count <= {WIDTH{1'b0}};
        direction <= 2'b00;
    end else if (load) begin
        count <= load_value;
        direction <= 2'b00;
    end else begin
        count <= next_count;
    end
end

assign zero = (count == {WIDTH{1'b0}});
assign overflow = ((mode == 2'b00 && count == {WIDTH{1'b1}} && next_count == {WIDTH{1'b0}}) ||
                    (mode == 2'b01 && count == {WIDTH{1'b0}} && next_count == {WIDTH{1'b1}}) ||
                    (mode == 2'b10 && ((count == {WIDTH{1'b1}} && next_count == {WIDTH{1'b0}}) ||
                                       (count == {WIDTH{1'b0}} && next_count == {WIDTH{1'b1}}))));

endmodule